INSERT INTO `berita` (`id`, `judul`, `slug`, `gambar_header`, `text_header`, `gambar_middle`, `text_middle`, `gambar_footer`, `text_footer`, `datetime`) VALUES
(1, 'Prof. Budi Mulyanti Ingatkan Pentingnya Peneliti Memiliki Ethical Clearance\r\n\r\n', 'prof-budi-mulyanti-ingatkan-pentingnya-peneliti-memiliki-ethical-clearance', 'ethical_clearance_header.jpg', 'Ethical Clearence merupakan instrumen pengukuran dalam keberterimaan secara etik dalam suatu rangkaian proses penelitian, yang bertujuan untuk melindungi subjek. Sehingga, disaat melakukan penelitian, perspektif kita harus menggunakan perspektif pemenuhan hak asasi manusia. Kita perlu memastikan bahwa penelitian yang sedang kita lakukan tidak mengekspliotasi subjek partisipan, tidak melakukan pelanggaran pada hak subjek partisipan, memberikan hak kepada partisipan untuk mengeluarkan pendapat, hak mendapatkan perlindungan privasinya, dan hak untuk tidak dieksploitasi. Hal ini merupakan sesuatu yang sangat penting, mengingat penelitian yang baik bukan semata-mata penelitian yang bisa diselesaikan, tetapi memenuhi hak subjek partisipan.\r\n\r\nKetua Pengurus Komisi Etik Penelitian Universitas Pendidikan Indonesia Periode 2023-2028 Prof. Dr. Budi Mulyanti, M.T., menyampaikan pernyataan tegas tersebut dalam sebuah wawancara, setelah menerima Surat Keputusan Rektor Universitas Pendidikan Indonesia Nomor 1745/UN40/HK/2023 Tentang Pengurus Komisi Etik Penelitian Universitas Pendidikan Indonesia Periode 2023-2028 di Gedung University Centre (UC) UPI, Ruang Teleconference lantai 1, Kampus UPI Jalan Dr. Setiabudhi Nomor 229 Bandung, Senin, (2/10/2023).\r\n\r\nDalam pernyataannya Prof. Budi Mulyanti menambahkan, ”Artinya, ethical clearance menjadi sebuah bentuk proteksi pertama untuk memastikan apakah penelitian ini bisa dilakukan atau tidak. Selain aspek metodologis, yang harus diperhatikan juga adalah aspek etikanya. Kadang-kadang satu penelitian bisa gagal dilakukan karena walaupun secara metodologi bisa dilakukan, tapi dia tidak bisa memenuhi aspek etikanya. Kita tentu tidak ingin UPI nanti dianggap menjadi lembaga yang tidak memperdulikan hak-hak dari partisipan tadi.” Prof. Budi Mulyanti menyatakan, agar para peneliti sebelum melakukan penelitiannya harus meminta izin terlebih dahulu. Perizinan tersebut apakah penelitian tersebut melanggar atau tidak terhadap subjek yang diteliti, terutama pada manusia dan hewan, dengan adanya surat ethical clearance yang menyatakan bahwa penelitian tersebut tidak melanggar atau tidak akan merugikan subjek, maka penelitian dapat dilanjutkan.\r\n\r\nNamun apabila Komisi Etik Penelitian meyakini akan adanya kerugian terhadap subjek manusia atau hewan, maka peneliti tersebut tidak dapat melakukan penelitian selanjutnya, atau peneliti harus merubah subjek penelitiannya.\r\n\r\n“Jadi intinya bahwa ethical clearance ini adalah untuk melindungi subjek penelitian terutama adalah hewan dan manusia agar tidak merugikan subjek. Subjek itu bukan betul-betul jadi objek tapi dia adalah subjeknya,” ungkap Prof. Budi Mulyanti.\r\n\r\nProf. Budi Mulyanti menambahkan, diterbitkannya ethical clearance, merupakan keharusan bagi seorang peneliti, ditambah ini merupakan tuntutan bagi perguruan tinggi yang ingin menuju World Class University. Jika UPI ingin memiliki predikat WCU, maka salah satu syarat agar dapat memenuhi predikat tersebut adalah penelitian-penelitian yang dilakukan oleh UPI harus memilki surat ethical clearance. Beberapa jurnal internasional memiliki persyaratan agar sebelum publish harus melampirkan surat ethical clearance pada risetnya.\r\n\r\nAdapun susunan Pengurus Komisi Etik Penelitian UPI Periode 2023-2028, yaitu Prof. Dr. .M. Solehuddin. M.Pd., M.A., sebagai Pengarah; Prof. Dr. Bunyamin Maftuh, M.Pd., M.A., sebagai Penanggung Jawab; kemudian Prof. Dr. Budi Mulyanti, M.T., sebagai Ketua Komisi Etik Penelitian UPI; Dr. Pipit Pitriani, M.Kes, Ph.D., sebagai Sekretaris dan para anggotanya terdiri dari Prof. Dr. Ahman, M.P.d., Prof. Dr. Elly Malihah, M.Si., Prof. Dr. Ida Hamidah, M.Si., dr. Hamidie Ronald Daniel Ray, M.Pd., Ph.D., Prof. Vina Adriany, Ph. D., dan Prof. Dr. Topik Hidayat, M.Si., Ph.D. (dodiangg/foto:arum)', NULL, NULL, NULL, NULL, '2024-07-25 16:47:43'),
(2, 'Kunjungan Komisi Etik Penelitian Universitas Pendidikan Indonesia (UPI) ke Universitas Malaya', 'kunjungan-komisi-etik-penelitian-upi-ke-universitas-malaya', 'gambar_header_kunjungan.jpg', 'Pada 7 November 2024, Komisi Etik Penelitian Universitas Pendidikan Indonesia (UPI) melakukan kunjungan resmi ke Komisi Etik Penelitian Universitas Malaya, Malaysia. Kunjungan ini bertujuan untuk mempererat hubungan kerja sama antar universitas sekaligus bertukar informasi dan pengalaman mengenai pengelolaan etika penelitian.\r\n\r\nDalam pertemuan tersebut, Prof. Dr. Budi Mulyanti, M.Si selaku pihak dari UPI disambut hangat oleh Assoc. Prof. Dr. Raida Abu Bakar dari Universitas Malaya. Kedua belah pihak berdiskusi mengenai berbagai topik penting, termasuk kebijakan etika penelitian, prosedur pengajuan izin etik, dan upaya meningkatkan kualitas penelitian berbasis ', 'gambar_middle_kunjungan.jpg', 'Selain itu, kunjungan ini juga menjadi momen simbolis dengan pertukaran plakat sebagai tanda persahabatan dan kolaborasi antara kedua institusi. Kegiatan ini diharapkan dapat menjadi awal dari kerja sama lebih lanjut dalam berbagai bidang penelitian dan akademik.\r\n\r\nKegiatan ini diharapkan dapat menjadi awal dari kerja sama lebih lanjut dalam berbagai bidang penelitian dan akademik.Komisi Etik Penelitian UPI berkomitmen untuk terus meningkatkan standar etika penelitian melalui kolaborasi dengan institusi internasional. Kunjungan ini merupakan langkah nyata untuk memperkuat jaringan global dan berbagi praktik terbaik dalam mendukung penelitian yang bertanggung jawab dan berkualitas.', NULL, NULL, '2024-11-27 14:23:29'),
(3, 'Komisi Etik UPI Adakan Pembekalan Penulisan Proposal untuk Ethical Approval', 'komisi-etik-upi-adakan-pembekalan-penulisan-proposal-untuk-ethical-approval', 'default.jpg', 'Bandung, [10 september 2024] – Komisi Etik Universitas Pendidikan Indonesia (UPI) menyelenggarakan kegiatan pembekalan penulisan proposal penelitian bagi para dosen, mahasiswa, dan peneliti di lingkungan FPTI dengan fokus pada persiapan mendapatkan ethical approval. Acara ini bertujuan untuk meningkatkan pemahaman dan keterampilan peserta dalam menyusun proposal yang sesuai dengan standar etika penelitian.\r\n\r\nMengusung tema “Membangun Penelitian Beretika untuk Dampak yang Lebih Bermakna”, pembekalan ini menghadirkan narasumber dari Komisi Etik UPI serta pakar etika penelitian yang berpengalaman di tingkat nasional. Peserta mendapatkan panduan komprehensif mengenai elemen penting yang harus ada dalam proposal penelitian, seperti metode penelitian yang beretika, pengelolaan data, serta prinsip perlindungan subjek penelitian.\r\n\r\nKetua Komisi Etik UPI, dalam sambutannya menyampaikan bahwa persetujuan etik merupakan prasyarat penting untuk memastikan penelitian tidak hanya memberikan kontribusi ilmiah, tetapi juga menghormati nilai-nilai kemanusiaan. “Kami ingin membantu para peneliti menyusun proposal yang memenuhi standar internasional, sehingga penelitian mereka dapat memberikan manfaat yang maksimal tanpa melanggar prinsip etika,” ujar beliau.\r\n\r\nSesi pembekalan mencakup beberapa topik utama:\r\n\r\nPrinsip-Prinsip Dasar Etika Penelitian – Termasuk aspek perlindungan subjek, informed consent, dan pengelolaan risiko.\r\nFormat dan Struktur Proposal untuk Ethical Approval – Penjelasan tentang komponen proposal yang harus dilengkapi, seperti deskripsi penelitian, metode, dan analisis risiko.\r\nStudi Kasus dan Evaluasi Proposal – Peserta diajak mempelajari contoh proposal dan mendapatkan masukan dari para ahli.\r\nSalah satu peserta, mengungkapkan manfaat dari pembekalan ini. “Kegiatan ini memberikan panduan yang sangat jelas tentang bagaimana menyusun proposal penelitian yang beretika. Ini akan mempermudah kami mendapatkan persetujuan dari Komisi Etik,” ujarnya.\r\n\r\nKomisi Etik UPI juga berkomitmen untuk mendampingi para peneliti melalui konsultasi individu bagi mereka yang memerlukan bantuan lebih lanjut dalam menyusun proposal. Ke depan, pelatihan serupa akan menjadi agenda rutin untuk mendukung ekosistem penelitian yang bertanggung jawab di lingkungan UPI.\r\n\r\nDengan adanya pembekalan ini, UPI berharap seluruh penelitian yang dilakukan di universitas dapat memenuhi standar etika dan memberikan kontribusi yang signifikan bagi pengembangan ilmu pengetahuan dan kesejahteraan masyarakat.', NULL, NULL, NULL, NULL, '2024-09-20 14:04:15'),
(4, 'Kegiatan Evaluasi dan Persiapan Sosialisasi Komisi Etik Goes to Fakultas/Kamda', 'kegiatan-evaluasi-dan-persiapan-sosialisasi-komisi-etik-goes-to-fakultas-kamda', 'gambar_header_sosialisasi.jpg', 'Tahun 2025 merupakan tahun ke 2 komisi etik melaksanakan dan menerima pembuatan dan evaluasi tentang etik penelitian. Saat ini terdapat antrean pengajuan etik yang perlu diproses. Oleh karena itu, Komisi Etik Penelitian Manusia menghentikan penerimaan pengajuan surat kelayakan etik hingga waktu yang belum ditentukan. \r\n\r\nAntrean ini juga berdampak pada durasi review dan penerbitan surat kelayakan etik. Bagi pengusul yang telah mengajukan surat kelayakan etik dan tidak berkenan menunggu, kami persilakan untuk mengajukan pengunduran atau penarikan berkas.', NULL, NULL, NULL, NULL, '2024-08-28 08:14:07'),
(5, 'Komisi Etik Penelitian UPI Dorong Para Peneliti untuk Ajukan Proposal dan Persetujuan Etik', 'komisi-etik-penelitian-upi-dorong-para-peneliti-untuk-ajukan-proposal-dan-persetujuan-etik', 'default.jpg', 'Bandung, [20 0ktober 2024] – Komisi Etik Penelitian Universitas Pendidikan Indonesia (UPI) mengajak para peneliti, baik dosen maupun mahasiswa, untuk lebih aktif dalam menyusun proposal penelitian dan mendapatkan persetujuan etik sebagai bagian dari standar penelitian yang bertanggung jawab. Langkah ini merupakan upaya strategis untuk memastikan setiap penelitian yang dilakukan memenuhi prinsip etika penelitian.\r\n\r\nKetua Komisi Etik Penelitian UPI, menegaskan bahwa persetujuan etik merupakan syarat penting untuk menjamin pelaksanaan penelitian yang menghormati hak, keselamatan, dan kesejahteraan subjek penelitian. “Kami mengundang para peneliti di UPI untuk mengajukan proposal mereka ke Komisi Etik. Persetujuan etik bukan sekadar formalitas, tetapi bagian dari upaya menjaga kualitas dan akuntabilitas penelitian yang dilakukan di lingkungan universitas,” ujarnya.\r\n\r\nUntuk mempermudah proses, Komisi Etik Penelitian UPI telah menyediakan panduan lengkap terkait pengajuan proposal dan standar persetujuan etik. Panduan ini mencakup langkah-langkah penyusunan proposal yang sesuai dengan prinsip-prinsip etika, seperti menghormati privasi subjek penelitian, memastikan persetujuan yang terinformasi, dan meminimalkan risiko pada subjek.\r\n\r\nSejumlah peneliti yang telah mendapatkan persetujuan etik menyampaikan manfaatnya, termasuk meningkatkan kredibilitas penelitian di tingkat nasional dan internasional. Salah satu peneliti, mengungkapkan bahwa proses ini membantu memperkuat desain penelitiannya dan membuka peluang untuk publikasi di jurnal bereputasi.\r\n\r\nSebagai bagian dari upaya meningkatkan partisipasi, Komisi Etik Penelitian UPI juga akan mengadakan workshop dan seminar tentang etika penelitian. Kegiatan ini bertujuan untuk memberikan pemahaman yang lebih mendalam kepada para peneliti tentang pentingnya etika dalam setiap tahap penelitian, mulai dari perencanaan hingga pelaporan hasil.\r\n\r\nDengan adanya persetujuan etik, UPI berharap dapat mendorong budaya penelitian yang bertanggung jawab, beretika, dan berdaya saing tinggi. “Kami ingin memastikan bahwa semua penelitian yang dilakukan di UPI tidak hanya bermanfaat bagi ilmu pengetahuan, tetapi juga memberikan dampak positif bagi masyarakat,” tutup Ketua Komisi Etik Penelitian', NULL, NULL, NULL, NULL, '2024-10-24 11:17:40'),
(6, 'Sosialisasi Etik Penelitian di Lingkungan UPI', 'sosialisasi-etik-penelitian-di-lingkungan-upi', 'gambar_header_lingkungan_upi.jpg', 'Komisi Etik Universitas Pendidikan Indonesia (UPI) menggelar kegiatan sosialisasi yang bertujuan untuk meningkatkan pemahaman sivitas akademika terhadap prinsip-prinsip etika akademik dan profesionalisme. Kegiatan ini dilaksanakan sebagai bagian dari komitmen UPI dalam menjaga integritas dan mutu akademik.\r\n\r\nSosialisasi yang dihadiri oleh dosen, peneliti dan mahasiswa ini mengangkat tema “Etika Akademik sebagai Pilar Utama Penyelenggaraan Pendidikan yang Bermartabat”. Dalam acara tersebut, Komisi Etik UPI memaparkan berbagai peraturan, pedoman, dan contoh kasus yang berkaitan dengan pelanggaran etika penelitian.\r\n\r\nKetua Komisi Etik UPI, Prof. Dr. Budi Mulyanti, M.Si, dalam sambutannya menyampaikan pentingnya memahami dan menerapkan etika dalam seluruh aspek penyelenggaraan pendidikan. \"Etika penelitian tidak hanya sebatas mematuhi peraturan, tetapi juga mencerminkan nilai-nilai integritas, keadilan, dan tanggung jawab. Dengan sosialisasi ini, kami berharap seluruh sivitas akademika UPI dapat bekerja sama dalam menjaga reputasi dan kualitas universitas,\" ungkapnya.\r\n\r\nKegiatan ini diisi dengan sesi diskusi interaktif, di mana peserta diberikan kesempatan untuk menyampaikan pertanyaan, pendapat, dan masukan terkait isu-isu etika yang sering terjadi. Beberapa isu yang menjadi perhatian utama meliputi plagiarisme, konflik kepentingan, dan pelanggaran tata kelola akademik.\r\nSebagai langkah lanjutan, Komisi Etik UPI berencana untuk mengadakan pelatihan khusus bagi dosen dan tenaga kependidikan, serta menyusun proposal agar sesuai etika penelitian Dengan demikian, diharapkan nilai-nilai etika dapat tertanam sejak awal di lingkungan akademik.\r\n\r\nMelalui kegiatan sosialisasi ini, UPI menegaskan komitmennya untuk terus mengedepankan nilai-nilai etika dalam mendukung visi menjadi universitas pelopor dan unggul di tingkat global.\r\n', NULL, NULL, NULL, NULL, '2024-08-12 08:21:18'),
(7, 'Pentingnya Etika dalam Penelitian: Membangun Kepercayaan dan Tanggung Jawab Ilmiah\r\n', 'pentingnya-etika-dalam-penelitian-membangun-kepercayaan-dan-tanggung-jawab-ilmiah', 'gambar_header_pentingnya.jpg', 'Etika dalam penelitian merupakan fondasi utama yang menjamin integritas, kepercayaan, dan keberlanjutan ilmu pengetahuan. Tanpa pedoman etika yang kuat, penelitian berisiko melanggar hak asasi manusia, menimbulkan dampak negatif bagi masyarakat, atau menghasilkan hasil yang tidak valid.', 'gambar_middle_pentingnya.jpg', 'Berikut adalah beberapa alasan pentingnya etika dalam penelitian:\r\n\r\n1. Perlindungan Subjek Penelitian\r\nEtika penelitian bertujuan untuk melindungi subjek penelitian, baik manusia, hewan, maupun lingkungan. Prinsip seperti informed consent (persetujuan berdasarkan informasi) memastikan bahwa partisipasi subjek bersifat sukarela, dengan pemahaman penuh terhadap tujuan, risiko, dan manfaat penelitian.\r\n\r\n2. Menjaga Kepercayaan Publik\r\nPenelitian yang mematuhi standar etika membangun kepercayaan antara peneliti, masyarakat, dan institusi. Masyarakat cenderung mendukung penelitian yang dilakukan secara transparan dan bertanggung jawab.\r\n\r\n3. Meningkatkan Kualitas Ilmu Pengetahuan\r\nEtika mendorong peneliti untuk mengikuti metode yang jujur dan valid, menghindari plagiarisme, fabrikasi, atau manipulasi data. Penelitian yang beretika menghasilkan temuan yang kredibel dan dapat diuji ulang oleh peneliti lain.\r\n\r\n4. Menghindari Dampak Negatif\r\nTanpa etika, penelitian berpotensi merugikan subjek atau masyarakat. Contoh kasus pelanggaran etika seperti eksperimen tanpa persetujuan subjek atau penggunaan data secara tidak bertanggung jawab menjadi peringatan penting akan bahaya penelitian yang tidak etis.\r\n\r\n5. Memenuhi Standar Global\r\nBanyak jurnal ilmiah dan institusi pendanaan menuntut penelitian yang diajukan telah mendapat persetujuan etik. Hal ini menunjukkan bahwa etika bukan hanya kewajiban moral, tetapi juga prasyarat untuk diterima di komunitas ilmiah internasional.\r\n\r\n6. Tanggung Jawab Sosial\r\nPenelitian sering kali berdampak pada masyarakat luas. Etika penelitian memastikan bahwa peneliti mempertimbangkan dampak sosial, budaya, dan lingkungan dari hasil penelitian mereka, sehingga penelitian dapat memberikan manfaat nyata tanpa merugikan pihak lain.', NULL, NULL, '2024-08-17 08:30:41'),
(8, 'Komisi Etik Penelitian di Universitas Pendidikan Indonesia (UPI)', 'komisi-etik-penelitian-di-universitas-pendidikan-indonesia-upi', 'default.jpg', 'Universitas Pendidikan Indonesia (UPI) adalah salah satu perguruan tinggi di Indonesia yang memiliki komitmen besar terhadap pengembangan penelitian yang berkualitas dan bertanggung jawab. Salah satu hal yang sangat diperhatikan dalam setiap kegiatan penelitian di UPI adalah aspek etika penelitian. Oleh karena itu, UPI memiliki Komisi Etik Penelitian yang berfungsi untuk mengawasi dan memastikan bahwa setiap penelitian yang dilakukan oleh sivitas akademika UPI mematuhi prinsip-prinsip etika yang berlaku.\r\n\r\n1. Tujuan dan Fungsi Komisi Etik Penelitian UPI\r\nKomisi Etik Penelitian di UPI bertujuan untuk menjaga kualitas dan integritas penelitian yang dilakukan oleh para peneliti di lingkungan kampus. Komisi ini memiliki fungsi sebagai lembaga yang melakukan evaluasi terhadap aspek etika dalam setiap proposal penelitian yang diajukan, baik yang dilakukan oleh mahasiswa, dosen, maupun peneliti eksternal yang bekerja sama dengan UPI.\r\n\r\n2. Tanggung Jawab Komisi Etik Penelitian\r\nKomisi Etik Penelitian UPI bertanggung jawab untuk memastikan bahwa penelitian yang dilakukan memenuhi standar etika penelitian yang berlaku secara internasional dan nasional. Beberapa tanggung jawab utama komisi ini antara lain:\r\n•	Pemeriksaan Proposal Penelitian: Komisi ini memeriksa proposal penelitian untuk memastikan bahwa penelitian tersebut tidak akan merugikan subjek atau peserta penelitian, serta memastikan bahwa metode penelitian yang digunakan tidak melanggar norma etika.\r\n•	Persetujuan Etik: Setiap penelitian yang melibatkan manusia sebagai subjek penelitian (misalnya, wawancara, eksperimen, survei) memerlukan persetujuan etik sebelum dilaksanakan. Komisi Etik Penelitian memberikan izin atau persetujuan etika berdasarkan tinjauan mereka terhadap proposal penelitian.\r\n•	Penyuluhan dan Sosialisasi: Komisi Etik Penelitian juga memiliki peran dalam melakukan edukasi dan sosialisasi kepada mahasiswa dan dosen mengenai pentingnya etika dalam penelitian. Hal ini termasuk pemahaman tentang perlindungan hak-hak peserta penelitian dan perlakuan yang adil terhadap semua pihak yang terlibat.\r\n\r\n3. Prinsip-Prinsip Etika Penelitian\r\nKomisi Etik Penelitian UPI berlandaskan pada sejumlah prinsip etika yang mengatur penelitian, di antaranya:\r\n•	Keadilan dan Kesetaraan: Peneliti harus memastikan bahwa setiap individu yang menjadi subjek penelitian diperlakukan dengan adil dan setara, tanpa adanya diskriminasi.\r\n•	Non-Maleficence (Tidak Menyakiti): Penelitian harus dilakukan dengan cara yang tidak membahayakan atau merugikan subjek penelitian secara fisik maupun psikologis.\r\n•	Beneficence (Memberikan Manfaat): Penelitian harus dirancang untuk memberikan manfaat, baik bagi perkembangan ilmu pengetahuan maupun untuk masyarakat luas.\r\n•	Autonomi: Peneliti harus memastikan bahwa partisipasi dalam penelitian bersifat sukarela dan dilakukan dengan persetujuan yang diinformasikan (informed consent).\r\n•	Kerahasiaan dan Privasi: Data pribadi dan informasi yang diperoleh dari subjek penelitian harus dijaga kerahasiaannya, dan digunakan hanya untuk tujuan penelitian yang telah disetujui.\r\n\r\n4. Proses Evaluasi Etik\r\nProses evaluasi etik di Komisi Etik Penelitian UPI biasanya melibatkan beberapa tahapan:\r\n1.	Pengajuan Proposal: Peneliti mengajukan proposal penelitian yang berisi tujuan, metodologi, serta rencana mengenai perlindungan hak-hak subjek penelitian.\r\n2.	Tinjauan oleh Komisi Etik: Komisi Etik Penelitian melakukan peninjauan terhadap proposal penelitian untuk memastikan bahwa penelitian tersebut mematuhi prinsip-prinsip etika yang telah ditetapkan.\r\n3.	Rekomendasi dan Persetujuan: Setelah dilakukan evaluasi, komisi memberikan rekomendasi, yang bisa berupa persetujuan penuh, persetujuan dengan revisi, atau penolakan terhadap proposal penelitian tersebut.\r\n4.	Pemantauan: Setelah penelitian berjalan, komisi etika dapat melakukan pemantauan untuk memastikan bahwa penelitian tetap sesuai dengan standar etika yang telah disepakati.\r\n\r\n5. Pentingnya Komisi Etik dalam Penelitian\r\nKomisi Etik Penelitian di UPI sangat penting karena penelitian yang tidak memperhatikan aspek etika bisa menimbulkan dampak negatif yang serius, baik bagi subjek penelitian, masyarakat, maupun dunia akademik itu sendiri. Etika penelitian tidak hanya berkaitan dengan perlindungan individu, tetapi juga dengan kredibilitas dan integritas ilmu pengetahuan. Penelitian yang dilakukan tanpa mematuhi standar etika bisa menciptakan keraguan terhadap validitas hasil penelitian dan merusak reputasi akademik.\r\n\r\n6. Kesimpulan\r\nKomisi Etik Penelitian di Universitas Pendidikan Indonesia memiliki peran yang sangat vital dalam memastikan bahwa setiap penelitian yang dilakukan oleh sivitas akademika UPI dilakukan dengan cara yang bertanggung jawab, adil, dan menghormati hak-hak individu. Dengan adanya komisi ini, UPI menegaskan komitmennya untuk melakukan penelitian yang tidak hanya menghasilkan ilmu pengetahuan baru, tetapi juga dilakukan dengan prinsip etika yang tinggi demi kepentingan bersama.', NULL, NULL, NULL, NULL, '2024-07-02 10:29:16'),
(9, 'Pentingnya Persetujuan Etik dalam Penelitian yang Melibatkan Manusia di UPI', 'pentingnya-persetujuan-etik-dalam-penelitian-yang-melibatkan-manusia-di-upi', 'default.jpg', 'Dalam penelitian yang melibatkan manusia sebagai subjek, persetujuan etik merupakan hal yang sangat penting untuk melindungi hak-hak peserta dan menjaga integritas penelitian. Di Universitas Pendidikan Indonesia (UPI), Komisi Etik Penelitian bertanggung jawab untuk mengawasi setiap proposal penelitian yang melibatkan interaksi langsung dengan manusia, seperti penelitian kualitatif, eksperimen, atau survei. Proses ini dimulai dengan peneliti yang menyusun proposal yang jelas, mencakup tujuan penelitian, metode yang digunakan, serta prosedur bagaimana data yang diperoleh akan diperlakukan dan dilindungi. Dalam proses persetujuan etik, peneliti diwajibkan untuk menyampaikan informasi yang lengkap dan transparan kepada subjek penelitian mengenai apa yang akan dilakukan selama penelitian berlangsung.\r\n\r\nKomisi Etik UPI memastikan bahwa semua prosedur penelitian dilakukan sesuai dengan prinsip dasar etika, seperti keadilan, keamanan, dan perlindungan privasi. Salah satu aspek penting adalah pemberian informed consent, di mana subjek penelitian harus diberikan kebebasan penuh untuk memilih apakah mereka ingin ikut serta dalam penelitian tanpa adanya paksaan. Selain itu, komisi juga memastikan bahwa setiap langkah penelitian yang melibatkan manusia meminimalkan potensi risiko bagi subjek, baik itu berupa cedera fisik, psikologis, atau pelanggaran privasi. Dengan adanya pengawasan ketat ini, Komisi Etik Penelitian UPI berkontribusi pada terciptanya penelitian yang beretika, aman, dan bermanfaat bagi semua pihak yang terlibat.', NULL, NULL, NULL, NULL, '2024-07-03 10:23:39'),
(10, 'Peran Komisi Etik Penelitian UPI dalam Meningkatkan Kualitas Penelitian Akademik', 'peran-komisi-etik-penelitian-upi-dalam-meningkatkan-kualitas-penelitian-akademik', 'default.jpg', 'Komisi Etik Penelitian di Universitas Pendidikan Indonesia (UPI) memiliki peran yang sangat penting dalam menjaga dan meningkatkan kualitas penelitian akademik yang dilakukan di kampus. Sebagai lembaga yang bertanggung jawab atas pengawasan etika penelitian, komisi ini memastikan bahwa setiap penelitian yang dilakukan oleh mahasiswa, dosen, atau peneliti lainnya mematuhi prinsip-prinsip etika yang tinggi. Komisi Etik tidak hanya berfungsi sebagai badan yang memberikan persetujuan terhadap proposal penelitian, tetapi juga mengawasi keseluruhan proses penelitian agar semua langkah yang diambil sesuai dengan standar etika yang berlaku. Dengan demikian, komisi ini berperan sebagai penjaga integritas ilmiah yang memastikan bahwa hasil penelitian yang dihasilkan dapat dipertanggungjawabkan dan tidak merugikan pihak manapun, baik itu subjek penelitian maupun masyarakat luas.\r\n\r\nSelain itu, Komisi Etik Penelitian UPI juga berperan dalam memastikan bahwa metode yang digunakan dalam penelitian tidak membahayakan subjek atau peserta yang terlibat. Setiap penelitian yang melibatkan manusia, data pribadi, atau informasi sensitif lainnya harus melewati proses evaluasi etik yang ketat untuk memitigasi potensi risiko yang mungkin muncul. Komisi Etik bertugas untuk menilai sejauh mana penelitian tersebut memberikan manfaat yang jelas dan tidak menyalahi prinsip-prinsip moral yang berlaku. Dengan pengawasan yang terperinci terhadap setiap tahapan penelitian, komisi ini membantu menciptakan penelitian yang tidak hanya inovatif, tetapi juga bertanggung jawab, yang pada gilirannya menghasilkan pengetahuan yang sah, dapat dipertanggungjawabkan, dan berkontribusi positif terhadap kemajuan ilmu pengetahuan dan masyarakat.', NULL, NULL, NULL, NULL, '2024-07-05 13:34:27'),
(11, 'Sosialisasi Etika Penelitian di UPI: Membangun Pemahaman Sejak Dini', 'sosialisasi-etika-penelitian-di-upi-membangun-pemahaman-sejak-dini', 'default.jpg', 'Komisi Etik Penelitian di Universitas Pendidikan Indonesia (UPI) tidak hanya berfungsi sebagai lembaga pengawas, tetapi juga memainkan peran penting sebagai fasilitator dalam memberikan edukasi tentang etika penelitian kepada sivitas akademika. Melalui berbagai program sosialisasi, seperti seminar, workshop, dan diskusi, Komisi Etik berupaya meningkatkan pemahaman mahasiswa dan dosen mengenai pentingnya etika dalam penelitian. Program-program ini bertujuan untuk menumbuhkan kesadaran bahwa penelitian yang dilakukan harus selalu menghormati hak-hak peserta, menjaga kerahasiaan data yang diperoleh, serta memastikan bahwa tujuan penelitian tidak merugikan pihak manapun. Dengan pendekatan ini, Komisi Etik berusaha menciptakan lingkungan akademik yang mendukung pelaksanaan penelitian yang bertanggung jawab dan beretika.\r\n\r\nSelain kegiatan sosialisasi, Komisi Etik Penelitian UPI juga bekerja sama dengan fakultas-fakultas di UPI untuk memasukkan materi tentang etika penelitian dalam kurikulum pembelajaran. Dengan demikian, mahasiswa sejak awal pendidikan sudah diajarkan mengenai prinsip-prinsip etika yang harus diikuti dalam penelitian. Hal ini diharapkan dapat membentuk pemahaman yang kuat tentang pentingnya etika dalam dunia ilmiah dan memastikan bahwa para peneliti muda di UPI akan mengintegrasikan nilai-nilai etika dalam setiap langkah penelitian yang mereka lakukan. Melalui upaya ini, Komisi Etik berperan besar dalam menciptakan budaya penelitian yang tidak hanya inovatif, tetapi juga bertanggung jawab dan bermoral.', NULL, NULL, NULL, NULL, '2024-07-07 14:36:21'),
(12, 'Kolaborasi Penelitian dan Etika: Peran Komisi Etik UPI dalam Penelitian Multinasional', 'kolaborasi-penelitian-dan-etik-peran-komisi-etik-upi-dalam-penelitian-multinasional', 'default.jpg', 'Penelitian yang melibatkan banyak negara atau lembaga seringkali dihadapkan pada tantangan etika yang lebih kompleks karena perbedaan budaya, kebijakan hukum, dan norma sosial yang berlaku di masing-masing negara. Dalam konteks ini, Komisi Etik Penelitian UPI berperan penting dalam memastikan bahwa penelitian multinasional tetap mematuhi standar etika yang universal, meskipun melibatkan berbagai pihak dengan latar belakang yang berbeda. Salah satu fokus utama Komisi Etik adalah memastikan bahwa setiap penelitian yang melibatkan banyak negara atau lembaga memiliki persetujuan etik yang jelas, menjaga perlindungan data pribadi, dan menjamin transparansi dalam publikasi hasil penelitian, sehingga hasil penelitian dapat dipertanggungjawabkan secara ilmiah.\r\n\r\nSelain itu, Komisi Etik juga bertanggung jawab untuk memastikan bahwa hak-hak subjek penelitian dihormati, terutama yang berkaitan dengan budaya dan nilai-nilai lokal. Dalam penelitian multinasional, penting untuk mempertimbangkan konteks budaya dan sosial dari setiap negara atau komunitas yang terlibat, agar penelitian tersebut tidak menimbulkan ketidakadilan atau merugikan pihak tertentu. Komisi Etik Penelitian UPI berperan dalam menjaga agar nilai-nilai lokal dan hak-hak individu tetap dihormati dalam setiap langkah penelitian, dari perencanaan hingga pelaporan hasilnya. Dengan demikian, komisi ini memastikan bahwa penelitian multinasional yang dilakukan di UPI tidak hanya sah secara ilmiah, tetapi juga etis dan responsif terhadap keberagaman budaya global.', NULL, NULL, NULL, NULL, '2024-07-09 15:37:11'),
(14, 'Komisi Etik Penelitian UPI dalam Pengawasan Penelitian Sosial dan Humaniora', 'komisi-etik-penelitian-upi-dalam-pengawasan-penelitian-sosial-dan-humaniora', 'default.jpg', 'Penelitian sosial dan humaniora seringkali melibatkan isu-isu sensitif yang berkaitan dengan kepercayaan agama, budaya, politik, serta masalah sosial lainnya. Mengingat karakteristik topik-topik tersebut, Komisi Etik Penelitian UPI memberikan perhatian khusus terhadap penelitian yang menyentuh area-area ini, untuk memastikan bahwa penelitian dilakukan dengan cara yang etis dan bertanggung jawab. Peneliti di bidang sosial dan humaniora diharapkan tidak hanya memenuhi standar ilmiah, tetapi juga menjaga keseimbangan antara objektivitas ilmiah dan penghormatan terhadap nilai-nilai sosial dan budaya yang ada. Komisi Etik berperan dalam memastikan bahwa subjek penelitian diperlakukan dengan penuh hormat dan penelitian tidak merugikan atau mengeksploitasi kelompok tertentu.\r\n\r\nLebih lanjut, Komisi Etik Penelitian UPI juga memastikan bahwa data yang diperoleh dari penelitian sosial dan humaniora dihormati dengan cara yang sesuai dan tidak disalahgunakan. Peneliti diminta untuk menjaga kerahasiaan dan integritas data yang dikumpulkan, serta memastikan bahwa data tersebut hanya digunakan untuk tujuan yang sah dan tidak merugikan individu atau kelompok yang terlibat. Dengan memberikan perhatian ekstra terhadap konteks sosial, budaya, dan politik yang relevan, Komisi Etik memastikan bahwa penelitian sosial dan humaniora yang dilakukan di UPI tidak hanya menghasilkan pengetahuan ilmiah, tetapi juga berkontribusi pada pembangunan sosial yang adil dan bermartabat.', NULL, NULL, NULL, NULL, '2024-07-11 11:39:51'),
(15, 'Panduan Lengkap Menyusun Proposal Penelitian yang Etis di UPI', 'panduan-lengkap-menyusun-proposal-penelitian-yang-etik-di-upi', 'default.jpg', 'Salah satu langkah awal yang penting dalam penelitian adalah penyusunan proposal yang etis, yang harus memenuhi standar etika yang telah ditetapkan. Komisi Etik Penelitian UPI menyediakan panduan yang jelas bagi peneliti yang akan mengajukan proposal penelitian. Panduan ini mencakup persyaratan yang harus dipenuhi untuk mendapatkan persetujuan etik, seperti penjelasan yang rinci mengenai tujuan penelitian, metodologi yang akan digunakan, dan bagaimana peneliti berencana untuk melindungi hak-hak subjek penelitian. Dalam hal ini, peneliti diminta untuk memastikan bahwa pendekatan yang digunakan tidak merugikan pihak manapun, serta memberikan informasi yang cukup bagi subjek untuk membuat keputusan yang terinformasi mengenai partisipasi mereka.\r\n\r\nSelain itu, proposal penelitian juga harus mencakup penjelasan mengenai bagaimana data yang diperoleh akan disimpan, diproses, dan digunakan, serta langkah-langkah yang diambil untuk menjaga kerahasiaan dan privasi informasi. Komisi Etik Penelitian UPI memberikan bantuan bagi peneliti dalam menyusun proposal yang sesuai dengan pedoman etik yang berlaku, agar proposal tersebut dapat disetujui. Proses ini memastikan bahwa setiap penelitian yang dilaksanakan tidak hanya sah secara ilmiah, tetapi juga etis, menjaga integritas penelitian, serta menghormati hak-hak individu yang terlibat dalam penelitian tersebut.', NULL, NULL, NULL, NULL, '2024-07-13 16:41:35'),
(16, 'Komisi Etik Penelitian UPI dan Dampaknya pada Integritas Ilmu Pengetahuan', 'komisi-etik-penelitian-upi-dan-dampaknya-pada-integritas-ilmu-pengetahuan', 'default.jpg', 'Keberadaan Komisi Etik Penelitian di Universitas Pendidikan Indonesia (UPI) memiliki peran yang sangat penting dalam menjaga integritas ilmu pengetahuan yang dihasilkan oleh sivitas akademika. Tanpa pengawasan yang tepat dari komisi ini, penelitian yang dilakukan bisa saja menghasilkan data yang tidak sah, tidak dapat dipertanggungjawabkan, atau bahkan menyesatkan. Komisi Etik memastikan bahwa setiap langkah dalam penelitian dilakukan sesuai dengan prinsip etika yang berlaku, sehingga hasil penelitian tidak hanya sah secara ilmiah, tetapi juga dapat dipertanggungjawabkan. Dengan adanya pengawasan yang ketat, penelitian di UPI memiliki landasan yang kuat untuk menghasilkan pengetahuan yang valid dan dapat diterima oleh komunitas ilmiah.\r\n\r\nLebih dari itu, keberadaan Komisi Etik Penelitian juga berkontribusi dalam meningkatkan kepercayaan masyarakat terhadap hasil penelitian yang dilakukan di UPI. Penelitian yang dilakukan dengan memperhatikan prinsip-prinsip etika yang tinggi akan menghasilkan pengetahuan yang tidak hanya bermanfaat, tetapi juga dihargai oleh masyarakat luas. Kepercayaan masyarakat terhadap hasil penelitian sangat penting, terutama ketika hasil penelitian tersebut berpengaruh pada kebijakan publik atau kehidupan sehari-hari. Dengan memastikan bahwa setiap penelitian dilakukan dengan etika yang baik, Komisi Etik Penelitian di UPI membantu menciptakan lingkungan penelitian yang kredibel dan bertanggung jawab, yang pada gilirannya berkontribusi pada kemajuan ilmu pengetahuan yang lebih baik dan bermanfaat bagi semua pihak.', NULL, NULL, NULL, NULL, '2024-07-22 13:42:43'),
(17, 'Komisi Etik Penelitian UPI dalam Pengelolaan Privasi dan Data Penelitian', 'komisi-etik-penelitian-upi-dalam-pengelolaan-privasi-dan-data-penelitian', 'default.jpg', 'Di era digital yang serba terhubung, pengelolaan data pribadi dan privasi dalam penelitian menjadi isu yang sangat krusial. Komisi Etik Penelitian UPI memberikan perhatian khusus terhadap bagaimana peneliti mengumpulkan, menyimpan, dan menggunakan data pribadi, terutama dalam penelitian yang melibatkan data sensitif. Setiap penelitian yang melibatkan data pribadi diwajibkan untuk mematuhi pedoman yang ketat mengenai pengendalian dan perlindungan data tersebut, memastikan bahwa informasi pribadi peserta penelitian tidak jatuh ke tangan yang tidak berwenang. Komisi Etik berperan untuk memastikan bahwa proses pengumpulan dan penggunaan data dilakukan dengan cara yang sah dan transparan, menjaga kerahasiaan informasi yang diberikan oleh subjek penelitian.\r\n\r\nSelain itu, Komisi Etik Penelitian UPI memastikan bahwa data pribadi yang dikumpulkan hanya digunakan untuk tujuan penelitian yang telah disetujui sebelumnya. Peneliti harus menjelaskan secara rinci bagaimana data akan diperlakukan dan melindungi hak privasi peserta sepanjang proses penelitian. Komisi Etik juga mengawasi agar data yang telah dikumpulkan tidak disalahgunakan untuk tujuan lain di luar penelitian, serta memastikan bahwa data tersebut disimpan dengan aman dan tidak dapat diakses oleh pihak yang tidak berwenang. Dengan adanya pengawasan yang ketat terhadap pengelolaan data pribadi, Komisi Etik membantu menciptakan penelitian yang tidak hanya sah secara ilmiah, tetapi juga etis dan bertanggung jawab terhadap perlindungan privasi individu.', NULL, NULL, NULL, NULL, '2024-07-28 10:45:06'),
(18, 'Peran Komisi Etik di Universitas Pendidikan Indonesia dalam Menjaga Integritas Akademik', 'peran-komisi-etik-di-upi', 'default.jpg', 'Universitas Pendidikan Indonesia (UPI) memiliki Komisi Etik sebagai lembaga strategis yang bertugas menjaga integritas akademik di lingkungan kampus.\r\n\r\nKomisi ini bertanggung jawab untuk memastikan bahwa seluruh civitas akademika, termasuk dosen, mahasiswa, dan tenaga kependidikan, mematuhi prinsip-prinsip etika akademik.\r\n\r\nDengan adanya Komisi Etik, UPI berupaya menciptakan budaya akademik yang jujur, adil, dan bertanggung jawab.', NULL, NULL, NULL, NULL, '2024-08-03 14:27:45'),
(19, 'Pentingnya Komisi Etik di UPI dalam Menangani Kasus Plagiarisme', 'pentingnya-komisi-etik-di-upi', 'default.jpg', 'Plagiarisme merupakan salah satu ancaman serius terhadap integritas akademik di perguruan tinggi, termasuk di Universitas Pendidikan Indonesia (UPI).\r\n\r\nUntuk mengatasi masalah ini, UPI membentuk Komisi Etik yang bertugas mencegah, mendeteksi, dan menangani kasus plagiarisme.\r\n\r\nKeberadaan Komisi Etik menjadi elemen penting dalam menjaga reputasi institusi serta memastikan bahwa karya ilmiah yang dihasilkan benar-benar orisinal.', NULL, NULL, NULL, NULL, '2024-08-07 09:38:12'),
(20, 'Tantangan yang Dihadapi Komisi Etik Universitas Pendidikan Indonesia dalam Penegakan Aturan', 'tantangan-komisi-etik-upi', 'default.jpg', 'Komisi Etik Universitas Pendidikan Indonesia (UPI) memiliki peran strategis dalam menegakkan aturan dan menjaga integritas akademik.\r\n\r\nNamun, dalam pelaksanaannya, terdapat sejumlah tantangan yang perlu dihadapi.\r\n\r\nSalah satu tantangan utama adalah rendahnya kesadaran dan pemahaman civitas akademika terhadap prinsip-prinsip etika akademik.', NULL, NULL, NULL, NULL, '2024-08-12 16:45:37'),
(21, 'Perbandingan Sistem Etik di UPI dengan Universitas Pendidikan Lain di Indonesia', 'perbandingan-sistem-etik-upi', 'default.jpg', 'Sistem etik di Universitas Pendidikan Indonesia (UPI) memiliki keunikan tersendiri jika dibandingkan dengan universitas pendidikan lainnya di Indonesia.\r\n\r\nSalah satu keunggulan UPI terletak pada keberadaan Komisi Etik yang berfungsi khusus untuk mengawasi dan menegakkan integritas akademik.\r\n\r\nKomisi ini bertugas menangani kasus-kasus etika akademik, termasuk plagiarisme, manipulasi data, dan pelanggaran proses pembelajaran.', NULL, NULL, NULL, NULL, '2024-08-18 11:22:54'),
(22, 'Komisi Etik dan Perlindungan Hak Cipta di Lingkungan Kampus UPI', 'komisi-etik-dan-perlindungan-hak-cipta', 'default.jpg', 'Universitas Pendidikan Indonesia (UPI) memiliki Komisi Etik yang berperan penting dalam melindungi hak cipta di lingkungan kampus.\r\n\r\nHak cipta, terutama dalam konteks karya ilmiah, menjadi isu yang krusial mengingat banyaknya tugas, penelitian, dan publikasi yang dihasilkan oleh mahasiswa, dosen, dan peneliti.\r\n\r\nKomisi Etik bertugas memastikan bahwa semua karya yang dihasilkan civitas akademika UPI bebas dari plagiarisme dan dilindungi hak ciptanya.', NULL, NULL, NULL, NULL, '2024-08-23 19:10:01'),
(23, 'Penerapan Etika dalam Penelitian di UPI: Tinjauan dari Komisi Etik', 'penerapan-etika-penelitian-upi', 'default.jpg', 'Penerapan etika dalam penelitian di Universitas Pendidikan Indonesia (UPI) merupakan upaya strategis untuk menjaga integritas dan kualitas hasil penelitian.\r\n\r\nKomisi Etik UPI bertanggung jawab mengawasi seluruh proses penelitian, mulai dari perencanaan, pelaksanaan, hingga publikasi hasil penelitian.\r\n\r\nSalah satu aspek penting dalam penerapan etika penelitian adalah perlindungan terhadap subjek penelitian, khususnya jika penelitian melibatkan manusia atau hewan.\r\n\r\nKomisi Etik memastikan bahwa penelitian tersebut telah memenuhi prinsip-prinsip etis, seperti persetujuan partisipan (informed consent), kerahasiaan data, dan non-diskriminasi. Setiap proposal penelitian yang melibatkan manusia atau hewan harus melalui proses tinjauan etis sebelum mendapat izin untuk dilaksanakan.\r\n\r\nKomisi Etik UPI juga menegakkan aturan ketat terkait kejujuran akademik dalam penelitian. Peneliti diwajibkan melaporkan data penelitian secara jujur dan tidak memanipulasi atau memalsukan hasil. Tindakan seperti fabrikasi (pembuatan data palsu) dan falsifikasi (manipulasi data) dianggap sebagai pelanggaran berat yang dapat dikenai sanksi akademik. Untuk memastikan keaslian hasil penelitian, Komisi Etik UPI mewajibkan pemeriksaan keaslian karya melalui perangkat lunak pendeteksi plagiarisme sebelum dipublikasikan di jurnal ilmiah. Kebijakan ini bertujuan melindungi hak kekayaan intelektual dan memastikan bahwa kontribusi penelitian yang dihasilkan benar-benar otentik.\r\n\r\nPenerapan etika penelitian di UPI juga berdampak positif terhadap reputasi dan kepercayaan publik terhadap institusi tersebut. Dengan adanya pengawasan dari Komisi Etik, kualitas penelitian yang dihasilkan lebih terjamin. Peneliti, baik dari kalangan dosen, mahasiswa, maupun tenaga peneliti, diharapkan mampu mengedepankan prinsip transparansi, akuntabilitas, dan tanggung jawab dalam setiap tahap penelitian. Dukungan ini tidak hanya memperkuat posisi UPI sebagai institusi pendidikan yang unggul dalam riset, tetapi juga mendorong terciptanya budaya akademik yang menjunjung tinggi etika dan nilai-nilai moral. Melalui langkah ini, UPI dapat menjadi contoh bagi perguruan tinggi lain dalam membangun ekosistem penelitian yang etis dan berintegritas tinggi.', NULL, NULL, NULL, NULL, '2024-08-27 08:15:45'),
(24, 'Peran Komisi Etik dalam Mengelola Konflik Kepentingan di Universitas Pendidikan Indonesia', 'peran-komisi-etik-dalam-konflik-kepentingan-upi', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memainkan peran sentral dalam mengelola konflik kepentingan di lingkungan kampus. Konflik kepentingan dapat terjadi ketika dosen, mahasiswa, atau tenaga kependidikan memiliki kepentingan pribadi yang dapat memengaruhi keputusan akademik, penelitian, atau kebijakan kampus. Contoh konflik kepentingan meliputi dosen yang menjadi pembimbing tugas akhir anggota keluarganya, peneliti yang memiliki kepentingan finansial dengan sponsor penelitian, atau panitia seleksi yang terlibat dengan peserta seleksi tertentu. Untuk mengatasi hal ini, Komisi Etik UPI bertugas mengidentifikasi, mengelola, dan mengurangi potensi konflik kepentingan guna menjaga objektivitas dan keadilan dalam pengambilan keputusan.\r\n\r\nSalah satu mekanisme pengelolaan konflik kepentingan di UPI adalah penerapan kebijakan deklarasi konflik kepentingan. Melalui kebijakan ini, dosen, peneliti, atau staf yang terlibat dalam pengambilan keputusan wajib mengungkapkan secara terbuka jika memiliki hubungan pribadi, keuangan, atau kepentingan lainnya yang dapat memengaruhi keputusan. Deklarasi ini bertujuan untuk menciptakan transparansi dan memungkinkan Komisi Etik melakukan langkah preventif. Selain itu, Komisi Etik juga dapat merekomendasikan pengalihan tugas atau penggantian personel yang terlibat dalam proses pengambilan keputusan guna menghindari bias atau ketidakadilan.\r\n\r\nPengelolaan konflik kepentingan yang efektif memiliki dampak positif terhadap kredibilitas dan reputasi UPI sebagai lembaga pendidikan tinggi. Dengan adanya pengawasan dari Komisi Etik, keputusan yang diambil dalam proses seleksi, penelitian, dan pengelolaan akademik lebih terjamin keadilannya. Kebijakan ini juga mendorong terciptanya budaya kejujuran, transparansi, dan akuntabilitas di lingkungan kampus. Melalui pengelolaan konflik kepentingan yang baik, UPI dapat meminimalkan potensi sengketa, meningkatkan kepercayaan publik, dan memperkuat ekosistem akademik yang profesional dan berintegritas.', NULL, NULL, NULL, NULL, '2024-08-30 10:45:00'),
(25, 'Pentingnya Pendidikan Etik untuk Mahasiswa di UPI', 'pentingnya-pendidikan-etik-untuk-mahasiswa-di-upi', 'default.jpg', 'Pendidikan etik bagi mahasiswa di Universitas Pendidikan Indonesia (UPI) memegang peranan penting dalam membentuk karakter dan integritas akademik. Sebagai calon pendidik, mahasiswa UPI tidak hanya dituntut menguasai ilmu pengetahuan dan keterampilan, tetapi juga nilai-nilai etika dan moral. Pendidikan etik bertujuan agar mahasiswa memiliki kesadaran dan tanggung jawab terhadap prinsip-prinsip kejujuran akademik, seperti menghindari plagiarisme, menghargai hak cipta, serta bersikap jujur dalam proses pembelajaran dan penelitian.', NULL, NULL, NULL, NULL, '2024-09-03 10:23:01'),
(26, 'Komisi Etik dan Pengaruhnya terhadap Kualitas Pembelajaran di UPI', 'komisi-etik-dan-pengaruhnya-terhadap-kualitas-pembelajaran-di-upi', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki pengaruh signifikan terhadap peningkatan kualitas pembelajaran di kampus. Sebagai lembaga pengawas etika, Komisi Etik bertanggung jawab untuk menjaga integritas akademik, memastikan keadilan dalam proses pembelajaran, dan menegakkan prinsip kejujuran di kalangan dosen, mahasiswa, dan tenaga kependidikan.', NULL, NULL, NULL, NULL, '2024-09-05 14:12:30'),
(27, 'Kajian Etik dalam Pengembangan Kurikulum di UPI', 'kajian-etik-dalam-pengembangan-kurikulum-di-upi', 'default.jpg', 'Kajian etik dalam pengembangan kurikulum di Universitas Pendidikan Indonesia (UPI) berperan penting dalam memastikan bahwa proses perancangan dan implementasi kurikulum berjalan sesuai dengan prinsip-prinsip moral dan akademik yang tinggi. Kurikulum yang dikembangkan harus tidak hanya memperhatikan kompetensi akademik, tetapi juga nilai-nilai etik yang dapat membentuk karakter mahasiswa.', NULL, NULL, NULL, NULL, '2024-09-07 09:45:56'),
(28, 'Komisi Etik di UPI: Studi Kasus Penanganan Kasus Etika oleh Mahasiswa', 'komisi-etik-di-upi-studi-kasus-penanganan-kasus-etika-oleh-mahasiswa', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran yang sangat penting dalam menangani kasus etika yang melibatkan mahasiswa. Salah satu studi kasus yang mencuat adalah ketika seorang mahasiswa diduga terlibat dalam plagiarisme saat mengumpulkan tugas akhir. Kasus ini memicu perlunya pengawasan yang lebih ketat dalam penegakan prinsip kejujuran akademik.', NULL, NULL, NULL, NULL, '2024-09-10 11:33:24'),
(29, 'Etika Penelitian di UPI: Tugas dan Peran Komisi Etik', 'etika-penelitian-di-upi-tugas-dan-peran-komisi-etik', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memainkan peran yang sangat penting dalam menjaga integritas dan kredibilitas penelitian yang dilakukan di lingkungan kampus. Etika penelitian mencakup serangkaian prinsip yang harus dipatuhi oleh para peneliti untuk memastikan bahwa penelitian dilakukan dengan cara yang bertanggung jawab, adil, dan menghormati hak asasi manusia.', NULL, NULL, NULL, NULL, '2024-09-12 08:24:11'),
(30, 'Menggali Peran Komisi Etik dalam Menjaga Kejujuran Akademik di UPI', 'menggali-peran-komisi-etik-dalam-menjaga-kejujuran-akademik-di-upi', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran sentral dalam menjaga dan menegakkan kejujuran akademik di seluruh aspek pendidikan. Kejujuran akademik mencakup integritas dalam pengerjaan tugas, ujian, dan penelitian, serta menghargai hak cipta dan karya ilmiah orang lain.', NULL, NULL, NULL, NULL, '2024-09-13 13:02:45'),
(31, 'Komisi Etik UPI dan Pengaruhnya terhadap Persepsi Masyarakat tentang Integritas Akademik', 'komisi-etik-upi-dan-pengaruhnya-terhadap-persepsi-masyarakat-tentang-integritas-akademik', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memegang peran yang sangat penting dalam membentuk persepsi masyarakat tentang integritas akademik. Keberadaan Komisi Etik memberikan jaminan bahwa UPI berkomitmen untuk menjaga standar etika yang tinggi dalam dunia pendidikan. Dengan menegakkan aturan tentang kejujuran akademik, seperti pencegahan plagiarisme, kecurangan dalam ujian, dan manipulasi data penelitian, Komisi Etik UPI berupaya menciptakan lingkungan yang adil dan transparan.', NULL, NULL, NULL, NULL, '2024-09-17 10:25:37'),
(32, 'Membangun Budaya Etik di UPI: Tantangan dan Solusi', 'membangun-budaya-etik-di-upi-tantangan-dan-solusi', 'default.jpg', 'Membangun budaya etik di Universitas Pendidikan Indonesia (UPI) merupakan langkah penting untuk menciptakan lingkungan akademik yang sehat, adil, dan penuh integritas. Namun, upaya ini tidak tanpa tantangan. Salah satu tantangan terbesar adalah kurangnya pemahaman yang mendalam tentang etika akademik di kalangan sebagian besar mahasiswa dan dosen. Banyak mahasiswa yang masih melihat tugas akademik sebagai kewajiban yang harus diselesaikan, tanpa memperhatikan aspek kejujuran dan integritas dalam pengerjaannya.', NULL, NULL, NULL, NULL, '2024-09-18 12:10:59'),
(33, 'Kode Etik untuk Dosen di UPI: Bagaimana Komisi Etik Berperan', 'kode-etik-untuk-dosen-di-upi-bagaimana-komisi-etik-berperan', 'default.jpg', 'Kode etik untuk dosen di Universitas Pendidikan Indonesia (UPI) merupakan pedoman yang sangat penting dalam menjaga integritas, kualitas pengajaran, dan profesionalisme dalam dunia akademik. Kode etik ini berfungsi sebagai acuan bagi dosen untuk menjalankan tugasnya dengan penuh tanggung jawab, menjaga hubungan yang sehat dengan mahasiswa, serta menjaga reputasi institusi. Komisi Etik di UPI memainkan peran yang krusial dalam menegakkan dan mengawasi pelaksanaan kode etik ini.', NULL, NULL, NULL, NULL, '2024-09-19 14:42:21'),
(34, 'Peran Komisi Etik dalam Penegakan Tata Tertib Mahasiswa di UPI', 'peran-komisi-etik-dalam-penegakan-tata-tertib-mahasiswa-di-upi', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran yang sangat penting dalam penegakan tata tertib mahasiswa. Tata tertib ini mencakup aturan-aturan yang berkaitan dengan perilaku mahasiswa dalam kehidupan akademik dan sosial di kampus, seperti kewajiban untuk menjaga kejujuran akademik, disiplin dalam menghadiri perkuliahan, serta menghormati hak dan kewajiban sesama mahasiswa. Komisi Etik bertugas untuk memastikan bahwa setiap mahasiswa mematuhi tata tertib yang telah ditetapkan oleh universitas.', NULL, NULL, NULL, NULL, '2024-10-21 16:30:05');
INSERT INTO `berita` (`id`, `judul`, `slug`, `gambar_header`, `text_header`, `gambar_middle`, `text_middle`, `gambar_footer`, `text_footer`, `datetime`) VALUES
(35, 'Studi Empiris tentang Implementasi Komisi Etik di UPI dalam Menangani Kasus Diskriminasi', 'studi-empiris-tentang-implementasi-komisi-etik-di-upi-dalam-menangani-kasus-diskriminasi', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memainkan peran penting dalam menjaga integritas akademik dan memastikan bahwa seluruh civitas akademika diperlakukan secara adil dan setara. Salah satu tantangan terbesar yang dihadapi oleh Komisi Etik adalah menangani kasus diskriminasi yang dapat muncul dalam lingkungan kampus. Diskriminasi, baik yang berbasis pada jenis kelamin, ras, agama, maupun latar belakang sosial, dapat merusak keharmonisan akademik dan menciptakan ketidakadilan di dalam institusi.', NULL, NULL, NULL, NULL, '2024-10-22 09:12:47'),
(36, 'Evaluasi Kebijakan Komisi Etik UPI dalam Menangani Kasus Penipuan Akademik', 'evaluasi-kebijakan-komisi-etik-upi-dalam-menangani-kasus-penipuan-akademik', 'default.jpg', 'Kebijakan Komisi Etik di Universitas Pendidikan Indonesia (UPI) dalam menangani kasus penipuan akademik, seperti plagiarisme, kecurangan dalam ujian, dan pemalsuan data penelitian, memiliki peran yang sangat penting dalam menjaga integritas akademik di lingkungan kampus...', NULL, NULL, NULL, NULL, '2024-10-05 12:34:56'),
(37, 'Menumbuhkan Kesadaran Etik di Kalangan Mahasiswa melalui Komisi Etik di UPI', 'menumbuhkan-kesadaran-etik-di-kalangan-mahasiswa-melalui-komisi-etik-di-upi', 'default.jpg', 'Kesadaran etik di kalangan mahasiswa adalah aspek penting dalam membentuk karakter dan integritas yang baik dalam dunia akademik dan profesional. Komisi Etik di Universitas Pendidikan Indonesia (UPI) memegang peran kunci dalam menumbuhkan kesadaran ini...', NULL, NULL, NULL, NULL, '2024-10-07 14:22:15'),
(38, 'Peran Komisi Etik dalam Pembentukan Karakter Akademik Mahasiswa di UPI', 'peran-komisi-etik-dalam-pembentukan-karakter-akademik-mahasiswa-di-upi', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran yang sangat penting dalam pembentukan karakter akademik mahasiswa. Karakter akademik mencakup nilai-nilai seperti kejujuran, kedisiplinan, tanggung jawab, dan integritas dalam menjalankan aktivitas akademik...', NULL, NULL, NULL, NULL, '2024-10-10 09:15:44'),
(39, 'Kode Etik UPI dalam Menanggulangi Pelanggaran Plagiarisme di Kalangan Mahasiswa', 'kode-etik-upi-dalam-menanggulangi-pelanggaran-plagiarisme-di-kalangan-mahasiswa', 'default.jpg', 'Universitas Pendidikan Indonesia (UPI) memiliki kode etik yang jelas dan tegas dalam menangani pelanggaran plagiarisme di kalangan mahasiswa. Plagiarisme, yang mencakup penyalinan karya ilmiah orang lain tanpa memberikan penghargaan yang layak, merupakan pelanggaran serius...', NULL, NULL, NULL, NULL, '2024-10-15 16:05:34'),
(40, 'Strategi Komisi Etik UPI dalam Mencegah Terjadinya Kecurangan Ujian', 'strategi-komisi-etik-upi-dalam-mencegah-terjadinya-kecurangan-ujian', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran yang sangat penting dalam menjaga integritas akademik, salah satunya dalam mencegah terjadinya kecurangan ujian di kalangan mahasiswa. Kecurangan ujian, yang meliputi penyontekan, penggunaan bahan yang tidak sah...', NULL, NULL, NULL, NULL, '2024-10-18 11:34:09'),
(41, 'Komisi Etik Universitas Pendidikan Indonesia dalam Mengawasi Penilaian Dosen', 'komisi-etik-universitas-pendidikan-indonesia-dalam-mengawasi-penilaian-dosen', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memainkan peran penting dalam mengawasi penilaian dosen terhadap mahasiswa untuk memastikan bahwa penilaian dilakukan secara objektif, adil, dan bebas dari bias. Penilaian yang tepat dan adil merupakan bagian integral dari integritas akademik...', NULL, NULL, NULL, NULL, '2024-10-20 13:27:55'),
(42, 'Pengaruh Keputusan Komisi Etik UPI terhadap Reputasi Universitas', 'pengaruh-keputusan-komisi-etik-upi-terhadap-reputasi-universitas', 'default.jpg', 'Keputusan-keputusan yang diambil oleh Komisi Etik Universitas Pendidikan Indonesia (UPI) memiliki dampak yang signifikan terhadap reputasi universitas, baik di tingkat nasional maupun internasional. Komisi Etik berfungsi untuk memastikan bahwa seluruh aktivitas akademik di UPI...', NULL, NULL, NULL, NULL, '2024-10-22 10:12:38'),
(43, 'Membina Etika Berbahasa di Lingkungan Kampus UPI melalui Komisi Etik', 'membina-etika-berbahasa-di-lingkungan-kampus-upi-melalui-komisi-etik', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran penting dalam membina etika berbahasa di lingkungan kampus, sebagai bagian dari upaya menjaga keharmonisan, saling menghormati, dan profesionalisme dalam interaksi akademik. Etika berbahasa mencakup penggunaan bahasa...', NULL, NULL, NULL, NULL, '2024-11-25 15:42:27'),
(44, 'Peran Komisi Etik dalam Menangani Kasus Pelanggaran Privasi Mahasiswa di UPI', 'peran-komisi-etik-dalam-menangani-kasus-pelanggaran-privasi-mahasiswa-di-upi', 'default.jpg', 'Komisi Etik Universitas Pendidikan Indonesia (UPI) memiliki peran penting dalam melindungi privasi mahasiswa sebagai bagian dari upaya menjaga integritas dan kepercayaan dalam lingkungan kampus. Pelanggaran privasi mahasiswa dapat berupa penyalahgunaan data pribadi, penyebaran informasi pribadi tanpa izin, atau pelanggaran terhadap hak privasi...', NULL, NULL, NULL, NULL, '2024-11-01 10:00:00'),
(45, 'Komisi Etik dan Penguatan Kepemimpinan Akademik di UPI', 'komisi-etik-dan-penguatan-kepemimpinan-akademik-di-upi', 'default.jpg', 'Komisi Etik Universitas Pendidikan Indonesia (UPI) memiliki peran strategis dalam penguatan kepemimpinan akademik di lingkungan kampus. Kepemimpinan akademik yang efektif membutuhkan integritas, keadilan, dan transparansi dalam pengambilan keputusan yang melibatkan berbagai aspek akademik...', NULL, NULL, NULL, NULL, '2024-11-03 14:22:15'),
(46, 'Keterlibatan Komisi Etik UPI dalam Penerapan Kebijakan Anti-Korupsi di Kampus', 'keterlibatan-komisi-etik-upi-dalam-penerapan-kebijakan-anti-korupsi-di-kampus', 'default.jpg', 'Komisi Etik Universitas Pendidikan Indonesia (UPI) memiliki peran vital dalam penerapan kebijakan anti-korupsi di lingkungan kampus, untuk memastikan bahwa setiap aspek pengelolaan akademik dan administrasi dilakukan dengan integritas yang tinggi dan bebas dari praktik korupsi...', NULL, NULL, NULL, NULL, '2024-11-05 13:05:30'),
(47, 'Pengaruh Komisi Etik terhadap Pembentukan Karakter Mahasiswa di UPI', 'pengaruh-komisi-etik-terhadap-pembentukan-karakter-mahasiswa-di-upi', 'default.jpg', 'Komisi Etik Universitas Pendidikan Indonesia (UPI) memainkan peran yang sangat penting dalam pembentukan karakter mahasiswa, yang merupakan salah satu tujuan utama pendidikan tinggi. Melalui peranannya dalam mengawasi dan menegakkan kode etik kampus, Komisi Etik membantu mahasiswa untuk menginternalisasi nilai-nilai integritas...', NULL, NULL, NULL, NULL, '2024-11-07 09:47:02'),
(48, 'Menjaga Keberagaman dan Toleransi di Kampus UPI: Peran Komisi Etik', 'menjaga-keberagaman-dan-toleransi-di-kampus-upi-peran-komisi-etik', 'default.jpg', 'Komisi Etik Universitas Pendidikan Indonesia (UPI) memegang peran yang sangat penting dalam menjaga keberagaman dan toleransi di lingkungan kampus. Sebagai lembaga yang bertanggung jawab atas penegakan standar etika, Komisi Etik berperan dalam menciptakan atmosfer yang inklusif, di mana setiap individu, terlepas dari latar belakang suku, agama...', NULL, NULL, NULL, NULL, '2024-11-10 11:30:17'),
(49, 'Evaluasi Implementasi Komisi Etik di UPI dalam Kasus Disiplin Mahasiswa', 'evaluasi-komisi-etik-upi-dalam-kasus-disiplin-mahasiswa', 'default.jpg', 'Komisi Etik Universitas Pendidikan Indonesia (UPI) memainkan peran penting dalam menangani kasus-kasus disiplin mahasiswa yang melibatkan pelanggaran terhadap kode etik kampus. Evaluasi terhadap implementasi Komisi Etik dalam menangani kasus disiplin mahasiswa sangat penting untuk memastikan bahwa proses penegakan aturan berjalan dengan adil, transparan, dan konsisten. Selama ini, Komisi Etik telah bekerja untuk menegakkan disiplin akademik melalui serangkaian mekanisme yang jelas, mulai dari pengawasan perilaku mahasiswa dalam kegiatan akademik hingga pengambilan keputusan yang melibatkan sanksi terhadap pelanggaran etik, seperti plagiarisme, kecurangan dalam ujian, atau perilaku tidak pantas lainnya.', NULL, NULL, NULL, NULL, '2024-11-16 14:35:22'),
(50, 'Penerapan Prinsip Etik dalam Pengelolaan Sumber Daya Manusia di UPI', 'penerapan-prinsip-etik-dalam-pengelolaan-sdm-upi', 'default.jpg', 'Penerapan prinsip etik dalam pengelolaan sumber daya manusia (SDM) di Universitas Pendidikan Indonesia (UPI) memiliki peran yang sangat penting dalam menciptakan lingkungan kerja yang profesional, transparan, dan penuh integritas. Sebagai lembaga pendidikan, UPI memiliki kewajiban untuk memastikan bahwa semua proses yang terkait dengan pengelolaan SDM, seperti rekrutmen, penilaian kinerja, promosi, dan pengembangan karir, dilakukan dengan adil dan berdasarkan pada prinsip keadilan, kesetaraan, serta transparansi.', NULL, NULL, NULL, NULL, '2024-11-18 11:22:17'),
(51, 'Etika Pengajaran di UPI: Perspektif Komisi Etik terhadap Dosen dan Mahasiswa', 'etika-pengajaran-upi-perspektif-komisi-etik-terhadap-dosen-dan-mahasiswa', 'default.jpg', 'Etika pengajaran di Universitas Pendidikan Indonesia (UPI) merupakan salah satu aspek penting dalam menjaga kualitas pendidikan dan membangun lingkungan akademik yang sehat. Perspektif Komisi Etik terhadap dosen dan mahasiswa sangat penting dalam menegakkan prinsip-prinsip etik dalam proses pembelajaran. Bagi dosen, Komisi Etik menekankan pentingnya penerapan standar etik yang tinggi dalam setiap aspek pengajaran, mulai dari penyampaian materi hingga interaksi dengan mahasiswa.', NULL, NULL, NULL, NULL, '2024-11-20 09:12:43'),
(52, 'Mengembangkan Sistem Pelaporan Etik di UPI: Tantangan dan Harapan', 'mengembangkan-sistem-pelaporan-etik-di-upi-tantangan-dan-harapan', 'default.jpg', 'Pengembangan sistem pelaporan etik di Universitas Pendidikan Indonesia (UPI) memiliki peranan penting dalam menjaga integritas dan kualitas akademik di kampus. Sistem pelaporan etik yang efektif akan memungkinkan dosen, mahasiswa, dan seluruh civitas akademika untuk melaporkan pelanggaran etik, seperti plagiarisme, kecurangan ujian, atau perilaku tidak profesional lainnya, dengan cara yang aman, transparan, dan tanpa takut adanya pembalasan.', NULL, NULL, NULL, NULL, '2024-12-02 10:35:22'),
(53, 'Komisi Etik dan Tanggung Jawab Sosial Universitas Pendidikan Indonesia', 'komisi-etik-dan-tanggung-jawab-sosial-universitas-pendidikan-indonesia', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran penting dalam memastikan bahwa universitas tidak hanya berfokus pada pencapaian akademik dan profesionalisme internal, tetapi juga dalam menjalankan tanggung jawab sosialnya sebagai lembaga pendidikan tinggi. Tanggung jawab sosial universitas mencakup kontribusi terhadap masyarakat, pengembangan nilai-nilai sosial, dan penanaman etika yang kuat dalam kegiatan akademik maupun non-akademik.', NULL, NULL, NULL, NULL, '2024-12-05 14:27:11'),
(54, 'Kepemimpinan Etik di UPI: Analisis Peran Komisi Etik dalam Mengarahkan Kebijakan', 'kepemimpinan-etik-di-upi-analisis-peran-komisi-etik-dalam-mengarahkan-kebijakan', 'default.jpg', 'Kepemimpinan etik di Universitas Pendidikan Indonesia (UPI) berperan sebagai landasan utama dalam menjaga kualitas akademik dan integritas institusi. Komisi Etik di UPI memiliki peran penting dalam mengarahkan kebijakan yang berkaitan dengan penerapan standar etik di seluruh aspek kegiatan universitas, mulai dari pengajaran, penelitian, hingga interaksi sosial antar civitas akademika.', NULL, NULL, NULL, NULL, '2024-12-08 11:42:35'),
(55, 'Kebijakan Anti-Diskriminasi di UPI dan Peran Komisi Etik dalam Implementasinya', 'kebijakan-anti-diskriminasi-di-upi-dan-peran-komisi-etik-dalam-implementasinya', 'default.jpg', 'Universitas Pendidikan Indonesia (UPI) memiliki komitmen untuk menciptakan lingkungan akademik yang inklusif dan bebas dari diskriminasi. Kebijakan anti-diskriminasi di UPI bertujuan untuk memastikan bahwa setiap individu, baik mahasiswa, dosen, maupun staf, diperlakukan secara adil tanpa memandang latar belakang suku, agama, ras, gender, atau status sosial.', NULL, NULL, NULL, NULL, '2024-12-11 09:17:54'),
(56, 'Tinjauan Hukum Terhadap Keputusan Komisi Etik Universitas Pendidikan Indonesia', 'tinjauan-hukum-terhadap-keputusan-komisi-etik-universitas-pendidikan-indonesia', 'default.jpg', 'Keputusan yang diambil oleh Komisi Etik Universitas Pendidikan Indonesia (UPI) memiliki dampak signifikan dalam menjaga integritas akademik dan profesionalisme civitas akademika. Sebagai lembaga yang bertanggung jawab atas penegakan kode etik di lingkungan universitas, Komisi Etik seringkali mengeluarkan keputusan terkait pelanggaran etik yang dilakukan oleh mahasiswa, dosen, atau staf.', NULL, NULL, NULL, NULL, '2024-12-13 13:05:47'),
(57, 'Komisi Etik UPI: Pengaruhnya dalam Meningkatkan Transparansi Akademik', 'komisi-etik-pengaruh-transparansi-akademik', 'default.jpg', 'Komisi Etik Universitas Pendidikan Indonesia (UPI) memiliki peran yang sangat penting dalam meningkatkan transparansi akademik di kampus. Sebagai lembaga yang bertugas menegakkan kode etik dan memastikan bahwa setiap kegiatan akademik berjalan sesuai dengan standar yang berlaku, Komisi Etik berfungsi untuk menciptakan lingkungan yang transparan, jujur, dan adil...', NULL, NULL, NULL, NULL, '2024-12-18 12:00:00'),
(58, 'Peran Komisi Etik dalam Penyelesaian Sengketa Akademik di UPI', 'peran-komisi-etik-sengketa-akademik', 'default.jpg', 'Komisi Etik Universitas Pendidikan Indonesia (UPI) memegang peran yang krusial dalam penyelesaian sengketa akademik yang timbul di lingkungan kampus. Sengketa akademik, seperti perselisihan antara mahasiswa dan dosen terkait penilaian, plagiarisme, atau pelanggaran lainnya, dapat mengganggu kelancaran proses pembelajaran dan merusak hubungan profesional di dalam komunitas akademik...', NULL, NULL, NULL, NULL, '2024-12-18 12:30:00'),
(59, 'Penerapan Etika Bisnis di Lingkungan Kampus UPI: Peran Komisi Etik', 'etika-bisnis-komisi-etik', 'default.jpg', 'Penerapan etika bisnis di lingkungan kampus Universitas Pendidikan Indonesia (UPI) sangat penting untuk menciptakan budaya akademik yang tidak hanya berfokus pada pengembangan ilmu pengetahuan, tetapi juga pada pembentukan karakter profesional yang etis. Dalam dunia pendidikan tinggi, penerapan prinsip-prinsip etika bisnis berfungsi untuk menjaga integritas, transparansi, dan akuntabilitas...', NULL, NULL, NULL, NULL, '2024-12-18 13:00:00'),
(60, 'Komisi Etik dan Keterbukaan Informasi Akademik di UPI', 'komisi-etik-keterbukaan-informasi-akademik', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran penting dalam memastikan keterbukaan informasi akademik yang transparan, adil, dan bertanggung jawab. Sebagai lembaga yang bertugas untuk mengawasi pelaksanaan kode etik di lingkungan kampus, Komisi Etik berperan dalam menjaga agar setiap informasi yang berkaitan dengan kegiatan akademik, seperti penilaian, kurikulum, dan pengelolaan sumber daya...', NULL, NULL, NULL, NULL, '2024-12-18 13:30:00'),
(61, 'Kajian Peran Komisi Etik dalam Penegakan Peraturan Kampus di UPI', 'kajian-peran-komisi-etik-penegakan-peraturan', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran sentral dalam penegakan peraturan kampus, baik yang berkaitan dengan aspek akademik maupun non-akademik. Sebagai lembaga yang bertugas untuk mengawasi dan menegakkan kode etik, Komisi Etik memastikan bahwa setiap civitas akademika UPI mematuhi aturan yang telah ditetapkan, guna menjaga keharmonisan dan integritas lingkungan kampus...', NULL, NULL, NULL, NULL, '2024-12-18 14:00:00'),
(62, 'Komisi Etik sebagai Pengawal Integritas Pendidikan di UPI', 'komisi-etik-pengawal-integritas-pendidikan-di-upi', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memainkan peran vital sebagai pengawal integritas pendidikan, dengan memastikan bahwa setiap proses akademik berjalan sesuai dengan prinsip-prinsip etika yang berlaku...', NULL, NULL, NULL, NULL, '2024-07-20 10:15:22'),
(63, 'Sosialisasi Kode Etik di UPI: Tantangan dan Solusi dari Perspektif Komisi Etik', 'sosialisasi-kode-etik-di-upi-tantangan-dan-solusi', 'default.jpg', 'Sosialisasi kode etik di Universitas Pendidikan Indonesia (UPI) merupakan langkah penting untuk memastikan bahwa seluruh civitas akademika memahami dan mengimplementasikan nilai-nilai etika yang berlaku...', NULL, NULL, NULL, NULL, '2024-08-05 13:27:36'),
(64, 'Peran Komisi Etik dalam Meminimalisir Kecurangan dalam Penulisan Skripsi di UPI', 'peran-komisi-etik-dalam-meminimalisir-kecurangan-dalam-penulisan-skripsi-di-upi', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran yang sangat penting dalam meminimalisir kecurangan yang dapat terjadi dalam penulisan skripsi. Kecurangan akademik, seperti plagiarisme, manipulasi data, atau penyalahgunaan sumber...', NULL, NULL, NULL, NULL, '2024-09-15 09:45:10'),
(65, 'Membangun Kepercayaan Publik terhadap Akademik UPI melalui Komisi Etik', 'membangun-kepercayaan-publik-terhadap-akademik-upi-melalui-komisi-etik', 'default.jpg', 'Kepercayaan publik terhadap kualitas dan integritas pendidikan di Universitas Pendidikan Indonesia (UPI) sangat bergantung pada kemampuan institusi untuk menjaga standar etika yang tinggi...', NULL, NULL, NULL, NULL, '2024-10-02 14:10:50'),
(66, 'Implementasi Komisi Etik UPI dalam Menangani Pelanggaran Etika Akademik oleh Dosen', 'implementasi-komisi-etik-upi-dalam-menangani-pelanggaran-etika-akademik-oleh-dosen', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran penting dalam menjaga integritas akademik di lingkungan kampus, termasuk dalam menangani pelanggaran etika akademik yang dilakukan oleh dosen...', NULL, NULL, NULL, NULL, '2024-11-18 16:20:30'),
(67, 'Peran Komisi Etik dalam Membangun Lingkungan Kampus yang Berintegritas di UPI', 'peran-komisi-etik-dalam-membangun-lingkungan-kampus-yang-berintegritas-di-upi', 'default.jpg', 'Komisi Etik di Universitas Pendidikan Indonesia (UPI) memiliki peran yang sangat vital dalam membangun lingkungan kampus yang berintegritas. Integritas akademik di lingkungan kampus mencakup kejujuran, tanggung jawab, dan transparansi dalam setiap aspek kehidupan akademik, mulai dari pengajaran, penelitian, hingga interaksi antar civitas akademika...', NULL, NULL, NULL, NULL, '2024-12-25 16:47:43'),
(68, 'Studi Kasus Pelanggaran Etik di UPI: Perspektif Komisi Etik dalam Penyelesaian Kasus', 'studi-kasus-pelanggaran-etik-di-upi-perspektif-komisi-etik-dalam-penyelesaian-kasus', 'default.jpg', 'Pelanggaran etik di universitas dapat muncul dalam berbagai bentuk, mulai dari plagiarisme, ketidakjujuran dalam ujian, hingga penyalahgunaan wewenang oleh dosen atau staf. Universitas Pendidikan Indonesia (UPI) memiliki Komisi Etik yang berperan penting dalam menangani dan menyelesaikan berbagai kasus pelanggaran etik tersebut...', NULL, NULL, NULL, NULL, '2024-11-14 10:22:31'),
(69, 'Peningkatan Kesadaran Etik Mahasiswa melalui Program Edukasi Komisi Etik di UPI', 'peningkatan-kesadaran-etik-mahasiswa-melalui-program-edukasi-komisi-etik-di-upi', 'default.jpg', 'Kesadaran etik di kalangan mahasiswa sangat penting untuk menciptakan lingkungan akademik yang sehat dan berintegritas. Universitas Pendidikan Indonesia (UPI) menyadari hal ini dan berkomitmen untuk meningkatkan kesadaran etik di kalangan mahasiswa melalui program edukasi yang dikelola oleh Komisi Etik...', NULL, NULL, NULL, NULL, '2024-12-03 11:16:54');

